const WORLD_RING: [number, number][] = [
  [-180, -85],
  [180, -85],
  [180, 85],
  [-180, 85],
  [-180, -85],
];

function copyRing(
  ring: readonly (readonly [number, number])[],
): [number, number][] {
  return ring.map(([lng, lat]): [number, number] => [lng, lat]);
}

/** World polygon with Germany cut out (RFC 7946: clockwise holes). */
export function buildGermanyInvertedMaskGeoJson(): Feature<Polygon> {
  return {
    type: 'Feature',
    properties: {},
    geometry: {
      type: 'Polygon',
      coordinates: [
        WORLD_RING.map(([x, y]): [number, number] => [x, y]),
        ...GERMANY_BORDER_RINGS.map((ring) => copyRing(ring).reverse()),
      ],
    },
  };
}

export function buildGermanyBorderOutlineGeoJson(): Feature<MultiLineString> {
  return {
    type: 'Feature',
    properties: {},
    geometry: {
      type: 'MultiLineString',
      coordinates: GERMANY_BORDER_RINGS.map(copyRing),
    },
  };
}
